import numpy as np
import time
from scipy.optimize import minimize


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    deadline = t0 + max(0.5, budget_seconds - 1.0)

    # ---------- build initial guess ----------
    if start is not None:
        init = np.asarray(start, dtype=float).copy()
    else:
        # hex packing
        pts = []
        rows = 6
        for row in range(rows):
            cols = 6 if row % 2 == 0 else 5
            for c in range(cols):
                if len(pts) >= n:
                    break
                x = (c + 0.5 + (0.25 if row % 2 else 0)) / 6.0
                y = (row + 0.5) / rows
                pts.append((x, y))
            if len(pts) >= n:
                break
        while len(pts) < n:
            pts.append((0.5, 0.5))
        init = np.array([[x, y, 0.03] for x, y in pts[:n]])

    # ---------- SLSQP formulation ----------
    # variables: x0,y0,r0, x1,y1,r1, ...
    def unpack(v):
        return v.reshape(n, 3)

    def obj(v):
        return -np.sum(v[2::3])

    # constraints
    def pos_r(v):
        return v[2::3] - 1e-6

    def wall_lo(v):
        p = unpack(v)
        return np.concatenate([p[:, 0] - p[:, 2], p[:, 1] - p[:, 2]])

    def wall_hi(v):
        p = unpack(v)
        return np.concatenate([1.0 - p[:, 0] - p[:, 2], 1.0 - p[:, 1] - p[:, 2]])

    def pair_con(v):
        p = unpack(v)
        dx = p[:, 0][:, None] - p[:, 0][None, :]
        dy = p[:, 1][:, None] - p[:, 1][None, :]
        d = np.sqrt(dx * dx + dy * dy + 1e-20)
        s = p[:, 2][:, None] + p[:, 2][None, :]
        iu = np.triu_indices(n, 1)
        return (d - s)[iu]

    cons = [
        {"type": "ineq", "fun": pos_r},
        {"type": "ineq", "fun": wall_lo},
        {"type": "ineq", "fun": wall_hi},
        {"type": "ineq", "fun": pair_con},
    ]

    # make start feasible-ish
    p = init.copy()
    p[:, 2] = np.maximum(p[:, 2], 1e-4)
    p[:, 0] = np.clip(p[:, 0], p[:, 2], 1 - p[:, 2])
    p[:, 1] = np.clip(p[:, 1], p[:, 2], 1 - p[:, 2])
    # shrink to fix pair violations
    for _ in range(30):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(p[i, 0]-p[j, 0], p[i, 1]-p[j, 1])
                s = p[i, 2] + p[j, 2]
                if d < s:
                    f = (d / s) * 0.999 if s > 0 else 1.0
                    p[i, 2] *= f
                    p[j, 2] *= f
                    changed = True
        if not changed:
            break

    v0 = p.reshape(-1)

    # ---------- run SLSQP with time guard via callback ----------
    best = {"v": v0.copy(), "score": np.sum(p[:, 2])}

    def callback(vk):
        sc = np.sum(vk[2::3])
        if sc > best["score"]:
            best["score"] = sc
            best["v"] = vk.copy()
        if time.process_time() > deadline - 0.2:
            raise StopIteration

    try:
        res = minimize(
            obj, v0, method="SLSQP",
            constraints=cons,
            options={"maxiter": 500, "ftol": 1e-10, "disp": False},
            callback=callback,
        )
        vf = res.x
        if np.sum(vf[2::3]) > best["score"]:
            best["score"] = np.sum(vf[2::3])
            best["v"] = vf.copy()
    except (StopIteration, Exception):
        pass

    # ---------- polish with local SLSQP from best ----------
    if time.process_time() < deadline - 0.5:
        try:
            res2 = minimize(
                obj, best["v"], method="SLSQP",
                constraints=cons,
                options={"maxiter": 200, "ftol": 1e-12, "disp": False},
            )
            if np.sum(res2.x[2::3]) > best["score"]:
                best["score"] = np.sum(res2.x[2::3])
                best["v"] = res2.x.copy()
        except Exception:
            pass

    # ---------- final strict feasibility ----------
    res_arr = unpack(best["v"]).copy()
    res_arr[:, 2] = np.maximum(res_arr[:, 2], 1e-6)
    # iterative shrink
    for _ in range(200):
        violated = False
        # walls
        for i in range(n):
            x, y, r = res_arr[i]
            m = 1e-9
            nr = min(r, x - m, 1 - m - x, y - m, 1 - m - y)
            if nr < r - 1e-15:
                res_arr[i, 2] = max(nr, 1e-9)
                violated = True
        # pairs
        for i in range(n):
            for j in range(i + 1, n):
                dx = res_arr[i, 0] - res_arr[j, 0]
                dy = res_arr[i, 1] - res_arr[j, 1]
                d = np.hypot(dx, dy)
                s = res_arr[i, 2] + res_arr[j, 2]
                if d < s + 1e-9 and s > 0:
                    f = (d - 1e-9) / s
                    if f < 1.0:
                        f = max(f, 0.0)
                        res_arr[i, 2] *= f
                        res_arr[j, 2] *= f
                        violated = True
        if not violated:
            break
    res_arr[:, 2] *= (1 - 1e-10)
    return res_arr

