        for i in range(n):
            xi, yi, ri = init[i]
            m = min(xi, 1-xi, yi, 1-yi)
            if m < ri:
                init[i, 2] = m
                changed = True
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(init[i, 0]-init[j, 0], init[i, 1]-init[j, 1])
                s = init[i, 2] + init[j, 2]
                if d < s and s > 0:
                    f = (d / s) * (1 - 1e-9)
                    init[i, 2] *= f
                    init[j, 2] *= f
                    changed = True
        if not changed:
            break

    # ---------------- SLSQP local optimisation ----------------
    def make_cons():
        cons = []
        for i in range(n):
            def c1(v, i=i):
                return v[3*i] - v[3*i+2]
            def c2(v, i=i):
                return 1.0 - v[3*i] - v[3*i+2]
            def c3(v, i=i):
                return v[3*i+1] - v[3*i+2]
            def c4(v, i=i):
                return 1.0 - v[3*i+1] - v[3*i+2]
