            p = vstart.reshape(n, 3)
            p[:, 2] = np.maximum(p[:, 2], 1e-3)
            p[:, 0] = np.clip(p[:, 0], p[:, 2] + 1e-6, 1 - p[:, 2] - 1e-6)
