        remaining = deadline - time.process_time()
        if remaining < 0.2:
            break
        try:
            res = minimize(
                neg_obj, vstart, method='SLSQP', constraints=cons,
                options={'maxiter': 200, 'ftol': 1e-12, 'disp': False},
            )
        except Exception:
            continue
        v = res.x
        p = v.reshape(n, 3)
        if feasible(p):
            sc = np.sum(p[:, 2])
            if sc > best_score:
                best_score = sc
                best = v.copy()

    res = best.reshape(n, 3).copy()

    # ---------------- strict feasibility cleanup ----------------
    for _ in range(300):
        x, y, r = res[:, 0], res[:, 1], res[:, 2]
        r = np.minimum(r, x)
        r = np.minimum(r, 1.0 - x)
        r = np.minimum(r, y)
